//#region 🔖️Varint
/// ➡️ Zigzag-encodes an `i64` into the `u64` domain: small magnitudes stay small
/// regardless of sign. See <https://protobuf.dev/programming-guides/encoding/#signed-ints>.
fn zigzag_encode(value: i64) -> u64 {
    ((value << 1) ^ (value >> 63)) as u64
}

/// ⬅️ Inverse of `zigzag_encode`.
fn zigzag_decode(value: u64) -> i64 {
    ((value >> 1) as i64) ^ -((value & 1) as i64)
}

/// ✏️ Writes `value` as an unsigned LEB128 varint (minimal length, max 10 bytes).
pub fn write_varint_u64(out: &mut Vec<u8>, value: u64) {
    let mut remaining = value;
    loop {
        let byte = (remaining & 0x7F) as u8;
        remaining >>= 7;
        if remaining == 0 {
            out.push(byte);
            break;
        }
        out.push(byte | 0x80);
    }
}

/// 📖️ Reads an unsigned LEB128 varint starting at `*pos`, advancing `*pos` past it.
/// Errors `Malformed` on a >10-byte (overlong) encoding, `Truncated` on running out of bytes.
pub fn read_varint_u64(bytes: &[u8], pos: &mut usize) -> Result<u64, PackRefusal> {
    let start = *pos;
    let mut result: u64 = 0;
    for i in 0..10usize {
        let idx = *pos;
        if idx >= bytes.len() {
            return Err(PackRefusal::Truncated(idx as u64));
        }
        let byte = bytes[idx];
        *pos += 1;
        let more = byte & 0x80 != 0;
        let payload = (byte & 0x7F) as u64;
        if i == 9 && (more || payload > 1) {
            return Err(PackRefusal::Malformed { kind:ValueRefusalKind::InvalidValue,what: "varint", offset: start as u64, detail: "overlong varint (exceeds 10 bytes / 64 bits)".to_string() });
        }
        result |= payload << (i as u32 * 7);
        if !more {
            return Ok(result);
        }
    }
    Err(PackRefusal::Malformed { kind:ValueRefusalKind::InvalidValue,what: "varint", offset: start as u64, detail: "overlong varint (exceeds 10 bytes)".to_string() })
}

/// ✏️ Writes `value` as a zigzag-encoded signed varint.
pub fn write_varint_i64(out: &mut Vec<u8>, value: i64) {
    write_varint_u64(out, zigzag_encode(value));
}

/// 📖️ Reads a zigzag-encoded signed varint starting at `*pos`.
pub fn read_varint_i64(bytes: &[u8], pos: &mut usize) -> Result<i64, PackRefusal> {
    let raw = read_varint_u64(bytes, pos)?;
    Ok(zigzag_decode(raw))
}

/// ✅️ True iff `bytes` is exactly one minimal-length varint (decoding then re-encoding
/// reproduces the input byte-for-byte, with nothing left over).
pub fn is_minimal_varint(bytes: &[u8]) -> bool {
    let mut pos = 0usize;
    let value = match read_varint_u64(bytes, &mut pos) {
        Ok(value) => value,
        Err(_) => return false,
    };
    if pos != bytes.len() {
        return false;
    }
    let mut reencoded = Vec::new();
    write_varint_u64(&mut reencoded, value);
    reencoded == bytes
}
//#endregion 🔖️Varint

//#region 🔖️Bytes
#[derive(Clone, Copy)]
enum ByteStorage<'a> { Slice(&'a [u8]), Paged(&'a crate::mutation::bytes::OwnedOperationBytes) }

/// 📏️ A checked finite range retains the exact borrowed source owner.
#[derive(Clone, Copy)]
pub struct ByteSpan<'a> { source: ByteStorage<'a>, offset: usize, length: usize }
impl<'a> ByteSpan<'a> {
    pub fn from_slice(bytes: &'a [u8]) -> Self { Self { source: ByteStorage::Slice(bytes), offset: 0, length: bytes.len() } }
    pub fn from_source(source: &'a crate::mutation::bytes::OwnedOperationBytes) -> Self { Self { source: ByteStorage::Paged(source), offset: 0, length: source.len() } }
    pub fn len(self) -> usize { self.length }
    pub fn is_empty(self) -> bool { self.length == 0 }
    pub fn get(self, offset: usize) -> Option<&'a u8> {
        if offset >= self.length { return None; }
        match self.source { ByteStorage::Slice(bytes) => bytes.get(self.offset + offset), ByteStorage::Paged(source) => source.byte_ref(self.offset + offset) }
    }
    pub fn slice(self, offset: usize, length: usize) -> Result<Self, PackRefusal> {
        if offset.checked_add(length).is_none_or(|end| end > self.length) { return Err(PackRefusal::Truncated(offset as u64)); }
        Ok(Self { source: self.source, offset: self.offset + offset, length })
    }
    pub fn contiguous(self) -> Option<&'a [u8]> { match self.source { ByteStorage::Slice(bytes) => Some(&bytes[self.offset..self.offset + self.length]), ByteStorage::Paged(_) => None } }
    pub fn iter(self) -> impl Iterator<Item = u8> + ExactSizeIterator + 'a { (0..self.length).map(move |index| *self.get(index).expect("checked borrowed operation byte range")) }
}
impl std::ops::Index<usize> for ByteSpan<'_> {
    type Output = u8;
    fn index(&self, index: usize) -> &u8 { self.get(index).expect("checked borrowed operation byte offset") }
}

/// 👓️ One bounds-checked cursor borrows either a slice or the genuine paged operation owner.
pub struct ByteReader<'a> { bytes: ByteSpan<'a>, pos: usize }
impl<'a> ByteReader<'a> {
    pub fn new(bytes: &'a [u8]) -> Self { Self::from_span(ByteSpan::from_slice(bytes)) }
    pub fn from_source(bytes: &'a crate::mutation::bytes::OwnedOperationBytes) -> Self { Self::from_span(ByteSpan::from_source(bytes)) }
    pub fn from_span(bytes: ByteSpan<'a>) -> Self { Self { bytes, pos: 0 } }
    pub fn fork(&self) -> Self { Self { bytes: self.bytes, pos: self.pos } }
    pub fn remaining(&self) -> usize { self.bytes.len() - self.pos }
    pub fn position(&self) -> usize { self.pos }
    pub fn read_span(&mut self, length: usize) -> Result<ByteSpan<'a>, PackRefusal> {
        if length > self.remaining() { return Err(PackRefusal::Truncated(self.pos as u64)); }
        let span = self.bytes.slice(self.pos, length)?;
        self.pos += length;
        Ok(span)
    }
    pub fn read_bytes(&mut self, length: usize) -> Result<&'a [u8], PackRefusal> {
        if length > self.remaining() { return Err(PackRefusal::Truncated(self.pos as u64)); }
        let span = self.bytes.slice(self.pos, length)?;
        let bytes = span.contiguous().ok_or_else(|| PackRefusal::from(semio_framework_value::ValueError::new(ValueRefusalKind::UnsupportedOwner, "contiguous read requires a slice source; use the borrowed byte range")))?;
        self.pos += length;
        Ok(bytes)
    }
    pub fn read_u8(&mut self) -> Result<u8, PackRefusal> { Ok(self.read_span(1)?[0]) }
    fn array<const N: usize>(&mut self) -> Result<[u8; N], PackRefusal> {
        let span = self.read_span(N)?;
        let mut bytes = [0; N];
        for (output, byte) in bytes.iter_mut().zip(span.iter()) { *output = byte; }
        Ok(bytes)
    }
    pub fn read_u16_le(&mut self) -> Result<u16, PackRefusal> { Ok(u16::from_le_bytes(self.array()?)) }
    pub fn read_u32_le(&mut self) -> Result<u32, PackRefusal> { Ok(u32::from_le_bytes(self.array()?)) }
    pub fn read_u64_le(&mut self) -> Result<u64, PackRefusal> { Ok(u64::from_le_bytes(self.array()?)) }
    pub fn read_f64_le(&mut self) -> Result<f64, PackRefusal> { Ok(f64::from_le_bytes(self.array()?)) }
    pub fn read_array32(&mut self) -> Result<[u8; 32], PackRefusal> { self.array() }
    pub fn read_varint_u64(&mut self) -> Result<u64, PackRefusal> {
        let start = self.pos;
        let mut result = 0;
        for index in 0..10 {
            let byte = self.read_u8()?;
            let payload = u64::from(byte & 127);
            if index == 9 && (byte & 128 != 0 || payload > 1) { return Err(PackRefusal::Malformed { kind: ValueRefusalKind::InvalidValue, what: "varint", offset: start as u64, detail: "overlong varint (exceeds 10 bytes / 64 bits)".into() }); }
            result |= payload << (index * 7);
            if byte & 128 == 0 { return Ok(result); }
        }
        Err(PackRefusal::Malformed { kind: ValueRefusalKind::InvalidValue, what: "varint", offset: start as u64, detail: "overlong varint (exceeds 10 bytes)".into() })
    }
    pub fn read_varint_i64(&mut self) -> Result<i64, PackRefusal> { self.read_varint_u64().map(zigzag_decode) }
}


/// ✍️ An append-only byte buffer with typed little-endian and varint writers.
#[derive(Default)]
pub struct ByteWriter {
    buf: Vec<u8>,
}

impl ByteWriter {
    pub fn new() -> Self {
        Self { buf: Vec::new() }
    }

    pub fn into_bytes(self) -> Vec<u8> {
        self.buf
    }

    pub fn write_u8(&mut self, v: u8) {
        self.buf.push(v);
    }

    pub fn write_u16_le(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }

    pub fn write_u32_le(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }

    pub fn write_u64_le(&mut self, v: u64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }

    pub fn write_f64_le(&mut self, v: f64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }

    pub fn write_varint_u64(&mut self, v: u64) {
        write_varint_u64(&mut self.buf, v);
    }

    pub fn write_varint_i64(&mut self, v: i64) {
        write_varint_i64(&mut self.buf, v);
    }

    pub fn write_bytes(&mut self, bytes: &[u8]) {
        self.buf.extend_from_slice(bytes);
    }
}

//#endregion 🔖️Bytes

//#region 🔖️Crc
/// 🌀️ CRC-32C (Castagnoli) polynomial, reflected form, as used by iSCSI/ext4/pack.
const CRC32C_POLY: u32 = 0x82F6_3B78;

/// 📐️ Builds the 256-entry CRC-32C lookup table at compile time — no runtime init, no
/// dependency on the `crc`/`crc32c` crates.
const fn build_crc32c_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0;
    while i < 256 {
        let mut crc = i as u32;
        let mut bit = 0;
        while bit < 8 {
            crc = if crc & 1 != 0 { (crc >> 1) ^ CRC32C_POLY } else { crc >> 1 };
            bit += 1;
        }
        table[i] = crc;
        i += 1;
    }
    table
}

const CRC32C_TABLE: [u32; 256] = build_crc32c_table();

/// 🧮️ Computes the CRC-32C (Castagnoli) checksum of `bytes`.
pub fn crc32c(bytes: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFF_FFFF;
    for &byte in bytes {
        let index = ((crc ^ byte as u32) & 0xFF) as usize;
        crc = (crc >> 8) ^ CRC32C_TABLE[index];
    }
    crc ^ 0xFFFF_FFFF
}

/// 🧮️ Retained CRC-32C state for fixed-page readers that must yield between input pages.
pub struct Crc32cCursor {
    crc: u32,
}

impl Crc32cCursor {
    pub const fn new() -> Self {
        Self { crc: 0xffff_ffff }
    }

    pub fn update_page(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            let index = ((self.crc ^ u32::from(byte)) & 0xff) as usize;
            self.crc = CRC32C_TABLE[index] ^ (self.crc >> 8);
        }
    }

    pub const fn finish(&self) -> u32 {
        !self.crc
    }
}

impl Default for Crc32cCursor {
    fn default() -> Self {
        Self::new()
    }
}
//#endregion 🔖️Crc

//#region 🔖️Codec
/// 🗜️ A pluggable segment payload compressor/decompressor, identified by `CodecId`.
/// `decompress` must validate `raw_len` against `limit` BEFORE allocating the output buffer.
pub trait CompressionCodec {
    fn id(&self) -> CodecId;

    fn compress(&self, raw: &[u8]) -> Result<Vec<u8>, PackRefusal>;

    fn decompress(&self, stored: &[u8], raw_len: u64, limit: u64) -> Result<Vec<u8>, PackRefusal>;
}

/// 🚫️ The identity codec (`CodecId(0)`) — no compression, used as the default and as
/// the fallback when a segment's compressed flag bit is unset.
pub struct NoCompression;

impl CompressionCodec for NoCompression {
    fn id(&self) -> CodecId {
        CodecId(0)
    }

    fn compress(&self, raw: &[u8]) -> Result<Vec<u8>, PackRefusal> {
        Ok(raw.to_vec())
    }

    fn decompress(&self, stored: &[u8], raw_len: u64, limit: u64) -> Result<Vec<u8>, PackRefusal> {
        if raw_len > limit {
            return Err(PackRefusal::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"NoCompression::decompress raw_len exceeds limit"});
        }
        if stored.len() as u64 != raw_len {
            return Err(PackRefusal::Malformed { kind:ValueRefusalKind::InvalidValue,what: "codec", offset: 0, detail: "identity codec stored length does not match raw_len".to_string() });
        }
        Ok(stored.to_vec())
    }
}
//#endregion 🔖️Codec

//#region 🔖️Deflate
/// 🗜️ Deflate compression (first-party `semio-framework-deflate`, RFC 1951 raw DEFLATE) as
/// a `CodecId(1)` `CompressionCodec`.
#[cfg(feature = "deflate")]
pub struct DeflateCodec;

#[allow(clippy::unnecessary_wraps)] // the `not(feature = "deflate")` arm below also returns `Result`
/// 📏️ Exact inline streaming measurement of the first-party fixed-Huffman producer.
#[cfg(feature="deflate")]
pub use semio_framework_deflate::DeflateMeasure;

pub fn deflate_compress(raw: &[u8]) -> Result<Vec<u8>, PackRefusal> {
    #[cfg(feature = "deflate")]
    {
        Ok(semio_framework_deflate::deflate(raw))
    }
    #[cfg(not(feature = "deflate"))]
    {
        let _ = raw;
        Err(PackRefusal::UnsupportedCodec(1))
    }
}

/// 🗜️ Compresses under the same cumulative caller admission as native field emission.
pub fn deflate_compress_controlled(raw:&[u8],control:&mut crate::value::native_encoding::NativeEncodeControl<'_>)->Result<Vec<u8>,PackRefusal>{
    #[cfg(feature="deflate")]
    {
        struct Admission<'a,'b>{control:&'a mut crate::value::native_encoding::NativeEncodeControl<'b>,phase:Option<semio_framework_deflate::DeflateEncodePhase>,completed:usize,total:usize}
        impl semio_framework_deflate::DeflateEncodeControl for Admission<'_,'_>{
            fn admit(&mut self,bytes:usize)->Result<(),crate::value::ValueError>{self.control.charge(bytes)}
            fn checkpoint(&mut self,event:semio_framework_deflate::DeflateEncodeProgress)->Result<(),crate::value::ValueError>{if self.phase!=Some(event.phase)||self.total!=event.total||event.completed<self.completed{self.control.begin_stage(event.total)?;self.phase=Some(event.phase);self.total=event.total;self.completed=0;}let advance=event.completed.checked_sub(self.completed).ok_or_else(||crate::value::ValueError::new(crate::value::ValueRefusalKind::InvariantViolated,"Deflate output progress regressed"))?;self.control.advance(advance)?;self.completed=event.completed;self.control.checkpoint()}
        }
        control.scoped_stage(|control|{semio_framework_deflate::deflate_controlled(raw,&mut Admission{control,phase:None,completed:0,total:0})}).map_err(PackRefusal::ValueRefusal)
    }
    #[cfg(not(feature="deflate"))]
    {let _=(raw,control);Err(PackRefusal::UnsupportedCodec(1))}
}

#[cfg(feature="deflate")]
fn deflate_grammar_kind(error:semio_framework_deflate::DeflateError)->ValueRefusalKind{
 match error{
  semio_framework_deflate::DeflateError::BadBlockType|semio_framework_deflate::DeflateError::BadStoredLength|semio_framework_deflate::DeflateError::BadHuffmanCode|semio_framework_deflate::DeflateError::BadDistance|semio_framework_deflate::DeflateError::UnexpectedEnd|semio_framework_deflate::DeflateError::OutputLimitExceeded=>ValueRefusalKind::InvalidValue,
 }
}

pub fn deflate_decompress(stored: &[u8], raw_len: u64, limit: u64) -> Result<Vec<u8>, PackRefusal> {
    if raw_len > limit {
        return Err(PackRefusal::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"DeflateCodec::decompress raw_len exceeds limit"});
    }
    #[cfg(feature = "deflate")]
    {
        let expected=usize::try_from(raw_len).map_err(|_|PackRefusal::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"DeflateCodec::decompress raw_len exceeds address space"})?;
        let out = semio_framework_deflate::inflate(stored, expected).map_err(|error| PackRefusal::Malformed { kind:deflate_grammar_kind(error),what: "deflate", offset: 0, detail: "decompression failed".to_string() })?;
        if out.len() as u64 != raw_len {
            return Err(PackRefusal::Malformed { kind:ValueRefusalKind::InvalidValue,what: "deflate", offset: 0, detail: "decompressed length mismatch".to_string() });
        }
        Ok(out)
    }
    #[cfg(not(feature = "deflate"))]
    {
        let _ = stored;
        Err(PackRefusal::UnsupportedCodec(1))
    }
}

/// 🌊️ One-byte retained DEFLATE result used by mounted pack readers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DeflateRetainedStep {
    NeedInput,
    Byte(u8),
    Complete,
}

/// 🧵️ The retirement step [`DeflateRetainedCursor::close_step`] answers with, re-exported because it
/// is part of this module's own public surface: a caller that drives the cursor to terminal must be
/// able to name the answer without taking a second, direct dependency on `semio-framework-deflate`
/// (CLAUDE.md — an exported API must not require an interface the client cannot reach through us).
/// `🎒️pack/📐️format/🦀️.rs` is exactly that caller, and reaches it as `crate::codec::…`.
#[cfg(feature = "deflate")]
pub use semio_framework_deflate::RetainedInflateCloseStep;

/// 🧵️ Incremental raw-DEFLATE decoder with exact producer handback and one output byte per grant.
#[cfg(feature = "deflate")]
pub struct DeflateRetainedCursor {
    inflater: Option<semio_framework_deflate::Inflater>,
    pending: Option<u8>,
    expected: u64,
    produced: u64,
    fault: Option<PackRefusal>,
    complete: bool,
    closed: bool,
}

#[cfg(feature = "deflate")]
impl DeflateRetainedCursor {
    pub fn try_new(expected: u64, limit: u64, maximum_allocation_bytes: usize) -> Result<Self, PackRefusal> {
        if expected > limit {
            return Err(PackRefusal::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"retained deflate raw length exceeds limit"});
        }
        let maximum_history_bytes = usize::try_from(limit).map_err(|_| PackRefusal::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"retained deflate history exceeds address space"})?;
        let inflater = semio_framework_deflate::Inflater::try_new_retained(maximum_history_bytes, maximum_allocation_bytes)
            .map_err(|error|match error{
                semio_framework_deflate::DeflateError::OutputLimitExceeded=>PackRefusal::ValueRefusal(ValueError::new(ValueRefusalKind::OwnershipLimit,"retained deflate physical ceiling")),
                semio_framework_deflate::DeflateError::BadBlockType|semio_framework_deflate::DeflateError::BadStoredLength|semio_framework_deflate::DeflateError::BadHuffmanCode|semio_framework_deflate::DeflateError::BadDistance|semio_framework_deflate::DeflateError::UnexpectedEnd=>PackRefusal::RetainedMalformed{kind:ValueRefusalKind::InvariantViolated,what:"deflate",offset:0,detail:"retained deflate constructor reported a grammar cause"},
            })?;
        Ok(Self { inflater: Some(inflater), pending: None, expected, produced: 0, fault: None, complete: false, closed: false })
    }

    pub fn reset(&mut self, expected: u64, limit: u64) -> Result<(), PackRefusal> {
        if !self.complete || self.closed || self.pending.is_some() || self.fault.is_some() {
            return Err(PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvariantViolated,what: "deflate", offset: self.produced, detail: "retained decoder cannot reset" });
        }
        if expected > limit{return Err(PackRefusal::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"retained deflate raw length exceeds limit"});}
        self.inflater
            .as_mut()
            .ok_or(PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvariantViolated,what: "deflate", offset: self.produced, detail: "decoder is closed" })?
            .reset_retained()
            .map_err(|_| PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvariantViolated,what: "deflate", offset: self.produced, detail: "retained decoder reset failed" })?;
        self.expected = expected;
        self.produced = 0;
        self.complete = false;
        Ok(())
    }

    pub fn next_allocation_bytes(&self) -> Option<usize> {
        self.inflater.as_ref().and_then(semio_framework_deflate::Inflater::next_retained_allocation_bytes)
    }

    pub fn reserve_allocation(
        &mut self,
        maximum_bytes: usize,
    ) -> Result<semio_framework_deflate::RetainedInflateAllocationStep, semio_framework_deflate::RetainedInflateAllocationError> {
        let result = self
            .inflater
            .as_mut()
            .expect("retained deflate allocation owner")
            .reserve_retained_history(maximum_bytes);
        if let Err(error) = result {
            if self.fault.is_none() {
                self.fault = Some(PackRefusal::RetainedAllocation { kind:error.kind,allocated_bytes:error.allocated_bytes,what: "deflate", offset: self.produced, detail: error.reason });
            }
        }
        result
    }

    pub fn allocated_bytes(&self) -> usize {
        self.inflater.as_ref().map_or(0, semio_framework_deflate::Inflater::retained_allocated_bytes)
    }

    pub fn retained_history_ptr(&self) -> Option<usize> {
        self.inflater.as_ref().and_then(semio_framework_deflate::Inflater::retained_history_ptr)
    }

    pub fn admit_byte(&mut self, byte: u8) -> Result<(), u8> {
        if !self.can_admit() {
            return Err(byte);
        }
        self.pending = Some(byte);
        Ok(())
    }

    pub fn grant(&mut self, input_complete: bool) -> Result<DeflateRetainedStep, PackRefusal> {
        if let Some(fault) = &self.fault {
            return Err(fault.clone());
        }
        let result = self.grant_inner(input_complete);
        match result {
            Ok(step) => Ok(step),
            Err(fault) => {
                self.fault = Some(fault);
                Err(self.fault.as_ref().expect("retained deflate first fault").clone())
            }
        }
    }

    fn grant_inner(&mut self, input_complete: bool) -> Result<DeflateRetainedStep, PackRefusal> {
        if self.complete {
            return Ok(DeflateRetainedStep::Complete);
        }
        if self.next_allocation_bytes().is_some() {
            return Ok(DeflateRetainedStep::NeedInput);
        }
        let inflater = self.inflater.as_mut().ok_or(PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvariantViolated,what: "deflate", offset: self.produced, detail: "decoder is closed" })?;
        match inflater.advance(&mut self.pending, input_complete) {
            Ok(semio_framework_deflate::InflateOutcome::Wrote(byte)) => {
                self.produced = self.produced.checked_add(1).ok_or(PackRefusal::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"retained deflate output overflow"})?;
                if self.produced > self.expected {
                    return Err(PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvalidValue,what: "deflate", offset: self.produced, detail: "decompressed length exceeds declared raw length" });
                }
                Ok(DeflateRetainedStep::Byte(byte))
            }
            Ok(semio_framework_deflate::InflateOutcome::Done) => {
                if self.pending.is_some() || self.produced != self.expected {
                    return Err(PackRefusal::RetainedMalformed { kind:ValueRefusalKind::InvalidValue,what: "deflate", offset: self.produced, detail: "decompressed length mismatch or trailing input" });
                }
                self.complete = true;
                Ok(DeflateRetainedStep::Complete)
            }
            Ok(semio_framework_deflate::InflateOutcome::NeedInput) => Ok(DeflateRetainedStep::NeedInput),
            Err(error) => Err(PackRefusal::RetainedMalformed { kind:deflate_grammar_kind(error),what: "deflate", offset: self.produced, detail: "incremental decompression failed" }),
        }
    }

    pub fn can_admit(&self) -> bool {
        !self.complete && !self.closed && self.fault.is_none() && self.pending.is_none() && self.next_allocation_bytes().is_none()
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.closed && self.pending.is_none() && self.inflater.is_none()
    }

    pub fn next_release_allocation_bytes(&self) -> Option<usize> {
        if self.pending.is_some() {
            return None;
        }
        self.inflater.as_ref().and_then(semio_framework_deflate::Inflater::next_retained_release_allocation_bytes)
    }

    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_deflate::RetainedInflateCloseStep {
        if self.closed {
            return semio_framework_deflate::RetainedInflateCloseStep::Complete;
        }
        if maximum_items == 0 && maximum_bytes == 0 {
            return semio_framework_deflate::RetainedInflateCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        if self.pending.is_some() {
            if maximum_items == 0 {
                return semio_framework_deflate::RetainedInflateCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            self.pending = None;
            return semio_framework_deflate::RetainedInflateCloseStep::Pending { released_items: 1, released_bytes: 0 };
        }
        let step = self
            .inflater
            .as_mut()
            .expect("retained deflate close owner")
            .close_retained_step(maximum_items, maximum_bytes);
        if step == semio_framework_deflate::RetainedInflateCloseStep::Complete {
            drop(self.inflater.take());
            self.complete = true;
            self.closed = true;
        }
        step
    }
}

#[cfg(feature = "deflate")]
impl Drop for DeflateRetainedCursor {
    fn drop(&mut self) {
        assert!(self.terminal_is_empty(), "retained deflate cursor reached Drop before terminal-empty close");
    }
}

#[cfg(feature = "deflate")]
impl CompressionCodec for DeflateCodec {
    fn id(&self) -> CodecId {
        CodecId(1)
    }

    fn compress(&self, raw: &[u8]) -> Result<Vec<u8>, PackRefusal> {
        deflate_compress(raw)
